package net.artisanmc.plugin.pack

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import java.io.ByteArrayInputStream
import java.io.File
import java.util.Base64
import java.util.zip.ZipInputStream
import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * The hub's builder against the editor's, byte for byte: each case of
 * `testdata/resource-pack-conformance.json` (regenerated by `npm run pack -- vectors --write`).
 * A drift names the entries that differ before the zip's SHA-1.
 */
class ResourcePackConformanceTest {
    private val vectors: JsonNode = ObjectMapper().readTree(File("../testdata/resource-pack-conformance.json"))

    private fun inputOf(case: JsonNode): PackInput {
        val projects = case["projects"].map { p ->
            val bytes = p["binaries"].fields().asSequence().associate { (path, b64) -> path to Base64.getDecoder().decode(b64.asText()) }
            PackProject(
                id = p["id"].asText(),
                files = p["files"].fields().asSequence().map { (path, content) -> PackFile(path, content.asText()) }.toList(),
                binaries = bytes.keys.toList(),
                binary = { bytes[it] },
                overlayImages = p["overlayImages"]?.map {
                    OverlayImageRequest(it["asset"].asText(), it["rise"]?.asInt(), it["bottom"]?.asInt())
                }.orEmpty(),
                folder = p["folder"]?.asText() ?: p["id"].asText(),
            )
        }
        return PackInput(
            projects = projects,
            containerTextures = case["containerTextures"].fields().asSequence().associate { (k, v) -> k to v.asText() },
            transparentContainers = case["vanillaGui"].asBoolean(),
            bedrockServerId = case["bedrock"]?.get("serverId")?.asText(),
        )
    }

    private fun entries(zip: ByteArray): Map<String, ByteArray> {
        val out = LinkedHashMap<String, ByteArray>()
        ZipInputStream(ByteArrayInputStream(zip)).use { z ->
            while (true) {
                val e = z.nextEntry ?: break
                out[e.name] = z.readBytes()
            }
        }
        return out
    }

    @Test
    fun `every case builds the editor's bytes`() {
        val failures = mutableListOf<String>()
        for (case in vectors["cases"]) {
            val name = case["name"].asText()
            val result = ResourcePackBuilder.build(inputOf(case))
            val entries = entries(result.zip)
            val drifted = case["entryHashes"].fields().asSequence()
                .filter { (path, hash) -> entries[path]?.let(::sha256Hex) != hash.asText() }
                .map { it.key }.toList()
            val listed = case["entries"].map { it.asText() }.toSet()
            val textY = Regex("^assets/artisan/font/text_y-?\\d+_h\\d+\\.json$")
            val textUp = Regex("^assets/artisan/font/text_up\\d+\\.json$")
            val extra = entries.keys.filter { it !in listed && !textY.matches(it) && !textUp.matches(it) }
            if (drifted.isNotEmpty() || extra.isNotEmpty() || result.sha1 != case["sha1"].asText()) {
                failures += "$name: sha1 ${result.sha1} (expected ${case["sha1"].asText()}), drifted $drifted, unexpected $extra"
            }
            val bedrock = case["bedrock"] ?: continue
            val built = result.bedrock
            if (built == null) {
                failures += "$name: no Bedrock pack"
                continue
            }
            val bedrockEntries = entries(built.zip)
            val bedrockDrifted = bedrock["entryHashes"].fields().asSequence()
                .filter { (path, hash) -> bedrockEntries[path]?.let(::sha256Hex) != hash.asText() }
                .map { it.key }.toList()
            val bedrockExtra = bedrockEntries.keys - bedrock["entries"].map { it.asText() }.toSet()
            if (bedrockDrifted.isNotEmpty() || bedrockExtra.isNotEmpty() || built.sha1 != bedrock["sha1"].asText()) {
                failures += "$name (Bedrock): sha1 ${built.sha1} (expected ${bedrock["sha1"].asText()}), drifted $bedrockDrifted, unexpected $bedrockExtra"
            }
        }
        assertEquals(emptyList(), failures)
    }
}
